using System.Text.Json.Nodes;
using Npgsql;
using static TWM.API.Services.StateService;
namespace TWM.API.Services;
public sealed partial class RelationalStore {
 static async Task Crud(NpgsqlConnection c,NpgsqlTransaction tx,string table,string action,JsonObject fields,JsonObject? key,CancellationToken ct){
  var sql=action=="insert"?"SELECT public.fn_crud_insert(@table,@fields::jsonb)":action=="update"?"SELECT public.fn_crud_update(@table,@key::jsonb,@fields::jsonb)":"SELECT public.fn_crud_delete(@table,@key::jsonb)";
  await Exec(c,tx,sql,ct,("table",table),("fields",fields.ToJsonString()),("key",key?.ToJsonString()??"{}"));
 }
 public async Task Write(NpgsqlConnection c,NpgsqlTransaction tx,string resource,JsonNode? previous,JsonNode? value,string rut,CancellationToken ct){
  var old=Rows(previous);var rows=Rows(value);
  if(resource=="categories"){
   async Task Walk(JsonArray nodes,int? parent){foreach(var node in nodes){var id=int.TryParse(Id(node),out var n)?n:await Next(c,tx,"categoría","id",ct);var exists=await Query(c,tx,"SELECT to_jsonb(t)::text FROM public.categoría t WHERE id=@id",ct,("id",id));await Crud(c,tx,"categoría",exists.Count==0?"insert":"update",new(){["id"]=id,["nombre"]=Text(node,"name"),["categoria_id"]=parent},new(){["id"]=id},ct);node!["id"]=id;await Walk(Rows(node["children"]),id);}}
   var tree=value!.AsObject();await Walk(Rows(tree["Productos"]),null);await Walk(Rows(tree["Servicios"]),null);var keep=new HashSet<int>();void Collect(JsonNode? n){foreach(var node in Rows(n)){keep.Add((int)Number(node,"id"));Collect(node?["children"]);}}Collect(tree["Productos"]);Collect(tree["Servicios"]);
   var current=await Query(c,tx,"SELECT to_jsonb(t)::text FROM public.categoría t",ct);foreach(var node in current.OrderByDescending(x=>Number(x,"id")))if(!keep.Contains((int)Number(node,"id")))await Crud(c,tx,"categoría","delete",new(),new(){["id"]=node!["id"]!.DeepClone()},ct);return;
  }
  if(resource=="wishlist"){
   await Exec(c,tx,"DELETE FROM public.desearp WHERE cliente_id=@rut;DELETE FROM public.desears WHERE cliente_id=@rut",ct,("rut",rut));foreach(var row in rows){var service=Text(row,"tipo",Text(row,"type"))=="Servicio";await Crud(c,tx,service?"desears":"desearp","insert",new(){[service?"servicio_id":"producto_id"]=DbId(row),["cliente_id"]=rut,["lista"]="Favoritos"},null,ct);}return;
  }
  var oldMap=old.ToDictionary(Id);foreach(var row in rows){var before=oldMap.GetValueOrDefault(Id(row));if(JsonNode.DeepEquals(before,row))continue;
   if(resource=="catalog"){
    var service=Text(row,"tipo")=="Servicio";var table=service?"servicio":"producto";var id=before==null?await Next(c,tx,table,"id",ct):DbId(before);var seller=Text(before,"ownerRut",rut);var category=await Query(c,tx,"SELECT to_jsonb(t)::text FROM public.categoría t WHERE nombre=@name ORDER BY id LIMIT 1",ct,("name",Text(row,"categoria")));if(category.Count==0)throw new ArgumentException("Selecciona una categoría existente en PostgreSQL.");
    var updatedDescription=new JsonObject{["imagen"]=Text(row,"imagen","/catalog/placeholder.svg"),["descripcion"]=Text(row,"descripcion"),["Material principal"]=Text(row,"material"),["Peso"]=Number(row,"peso")/1000,["Ancho"]=Number(row?["dimensiones"],"ancho"),["Alto"]=Number(row?["dimensiones"],"alto"),["Fondo"]=Number(row?["dimensiones"],"fondo"),["Modalidad"]=Text(row,"modalidad")};
    await Exec(c,tx,"INSERT INTO shopping_ui.listing_state(id,active) VALUES(@id,@active) ON CONFLICT(id) DO UPDATE SET active=EXCLUDED.active",ct,("id",CatalogId(service?"Servicio":"Producto",id.ToString(),seller)),("active",Text(row,"estado")!="Borrador"));
    var currentRecord=before==null?new JsonArray():await Query(c,tx,$"SELECT jsonb_build_object('attributes',{(service?"descripcion":"descripción")})::text FROM public.{table} WHERE id=@id",ct,("id",id));var description=currentRecord.FirstOrDefault()?["attributes"]?.DeepClone().AsObject()??new JsonObject();foreach(var pair in updatedDescription)description[pair.Key]=pair.Value?.DeepClone();description["relacionados"]=row?["relacionados"]?.DeepClone()??description["relacionados"]?.DeepClone()??new JsonArray();description["imagenes"]=row?["imagenes"]?.DeepClone()??new JsonArray();description["comunas"]=row?["comunas"]?.DeepClone()??description["comunas"]?.DeepClone()??new JsonArray();
    var fields=new JsonObject{["nombre"]=Text(row,"nombre"),["categoria_id"]=Number(category[0],"id"),["edadminima"]=Number(row,"edad"),[service?"descripcion":"descripción"]=description,["activo"]=Text(row,"estado")!="Borrador"};
    if(service){fields["precio"]=Math.Round(Number(row,"precio")/1.19m);fields["duracion"]=Text(row,"duracion","60 minutes").Replace("minutos","minutes").Replace("horas","hours");}
    if(before==null)fields["id"]=id;var attributesChanged=before==null||new[]{"relacionados","nombre","categoria","edad","descripcion","imagen","imagenes","material","marca","peso","dimensiones","estado","duracion","modalidad"}.Any(key=>!JsonNode.DeepEquals(before[key],row?[key]))||service&&Number(before,"precio")!=Number(row,"precio");if(attributesChanged)await Crud(c,tx,table,before==null?"insert":"update",fields,new(){["id"]=id},ct);
    if(service){if(before==null)await Crud(c,tx,"ofrecers","insert",new(){["servicio_id"]=id,["emprendedor_id"]=seller,["fechainicio"]=DateTime.Today.ToString("yyyy-MM-dd")},null,ct);}
    else{
     var variants=Rows(row?["variantes"]);if(variants.Count==0)variants=new JsonArray(new JsonObject{["sku"]="nuevo",["stock"]=Number(row,"stock"),["price"]=Number(row,"precio"),["color"]=Text(row,"color"),["size"]=Text(row,"talla")});
     foreach(var variant in variants){var oldVariant=Rows(before?["variantes"]).FirstOrDefault(x=>Text(x,"sku")==Text(variant,"sku"));var variantId=oldVariant==null?await Next(c,tx,"caracteristicas","id",ct):(int)Number(oldVariant,"dbId",Number(oldVariant,"sku"));
      if(oldVariant==null){await Crud(c,tx,"caracteristicas","insert",new(){["id"]=variantId,["peso"]=Number(row,"peso")/1000,["color"]=Text(variant,"color"),["marca"]=Text(row,"marca"),["material"]=Text(row,"material"),["medidas"]=Text(row,"tamano"),["talla"]=Text(variant,"size")},null,ct);variant!["sku"]=variantId.ToString();variant["dbId"]=variantId;await Crud(c,tx,"poseer","insert",new(){["caracteristicas_id"]=variantId,["producto_id"]=id,["precio"]=Math.Round(Number(variant,"price")/1.19m)},null,ct);await Crud(c,tx,"ofrecerp","insert",new(){["producto_id"]=id,["emprendedor_id"]=seller,["caracteristicas_id"]=variantId,["fechainicio"]=DateTime.Today.ToString("yyyy-MM-dd"),["stock"]=Number(variant,"stock"),["precio"]=Math.Round(Number(variant,"price")/1.19m)},null,ct);}
      else if(!JsonNode.DeepEquals(oldVariant,variant)){await Crud(c,tx,"caracteristicas","update",new(){["color"]=Text(variant,"color"),["talla"]=Text(variant,"size"),["marca"]=Text(row,"marca"),["material"]=Text(row,"material"),["peso"]=Number(row,"peso")/1000},new(){["id"]=variantId},ct);await Crud(c,tx,"ofrecerp","update",new(){["stock"]=Number(variant,"stock"),["precio"]=Math.Round(Number(variant,"regularPrice",Number(variant,"price"))/1.19m)},new(){["producto_id"]=id,["emprendedor_id"]=seller,["caracteristicas_id"]=variantId},ct);}
     }
     foreach(var removed in Rows(before?["variantes"]).Where(v=>!variants.Any(n=>Text(n,"sku")==Text(v,"sku"))))await Crud(c,tx,"ofrecerp","update",new(){["stock"]=0,["fechafin"]=DateTime.Today.AddDays(1).ToString("yyyy-MM-dd")},new(){["producto_id"]=id,["emprendedor_id"]=seller,["caracteristicas_id"]=Number(removed,"dbId")},ct);
    }
    if(row?["oferta"]==null&&before?["oferta"]!=null)await Exec(c,tx,$"DELETE FROM public.{(service?"ofertars":"ofertarp")} WHERE {(service?"servicio_id":"producto_id")}=@id AND emprendedor_id=@seller AND (ffin IS NULL OR ffin>=CURRENT_DATE)",ct,("id",id),("seller",seller));
    if(row?["oferta"] is JsonObject offer&&!JsonNode.DeepEquals(before?["oferta"],row["oferta"])){var offerId=await Next(c,tx,"oferta","id",ct);await Crud(c,tx,"oferta","insert",new(){["id"]=offerId,["precio"]=Math.Round(Number(offer,"precio")/1.19m)},null,ct);var tableOffer=service?"ofertars":"ofertarp";await Exec(c,tx,$"DELETE FROM public.{tableOffer} WHERE {(service?"servicio_id":"producto_id")}=@id AND emprendedor_id=@seller AND ffin>=CURRENT_DATE",ct,("id",id),("seller",seller));foreach(var variant in service?new JsonArray(new JsonObject()):Rows(row["variantes"])){var offerRow=new JsonObject{[service?"servicio_id":"producto_id"]=id,["emprendedor_id"]=seller,["oferta_id"]=offerId,["finicio"]=Text(offer,"inicio"),["ffin"]=Text(offer,"fin")};if(!service)offerRow["caracteristicas_id"]=int.Parse(Text(variant,"sku"));await Crud(c,tx,tableOffer,"insert",offerRow,null,ct);}}
   }
   else if(resource=="orders"){
    if(before==null)throw new ArgumentException("Los pedidos se crean por checkout.");await Crud(c,tx,"venta","update",new(){["estado"]=DbStatus(Text(row,"status"))},new(){["id"]=DbId(before)},ct);if(Text(row,"status")!=Text(before,"status"))await Exec(c,tx,"INSERT INTO shopping_ui.order_events(order_id,status) VALUES(@id,@status)",ct,("id",DbId(before)),("status",Text(row,"status")));
    if(row?["dispatch"] is JsonObject dispatch&&before?["dispatch"] is JsonObject oldDispatch){var shipmentId=(int)Number(oldDispatch,"dbId",Number(oldDispatch,"tracking"));if(Text(dispatch,"carrier")!=Text(oldDispatch,"carrier"))await Crud(c,tx,"envio","update",new(){["empresa"]=Text(dispatch,"carrier")},new(){["seguimiento"]=shipmentId},ct);if(Text(dispatch,"tracking")!=Text(oldDispatch,"tracking")){if(Text(dispatch,"tracking").Length is <1 or >80)throw new ArgumentException("Código de seguimiento inválido.");await Exec(c,tx,"INSERT INTO shopping_ui.shipment_tracking VALUES(@id,@code) ON CONFLICT(shipment_id) DO UPDATE SET external_code=EXCLUDED.external_code",ct,("id",shipmentId),("code",Text(dispatch,"tracking")));}var status=Text(row,"status");if(status is "Enviado" or "En reparto" or "Entregado" or "Recibido"){var shippingState=status=="Recibido"?"Entregado":DbStatus(status);await Exec(c,tx,"UPDATE public.envio SET estado=@status,fechallegada=CASE WHEN @status='Entregado' THEN CURRENT_DATE ELSE fechallegada END WHERE seguimiento=@id",ct,("id",shipmentId),("status",shippingState));}}

   }
   else if(resource=="quotes"){
    if(before==null){var detail=new JsonArray(Rows(row?["items"]).Select(item=>(JsonNode?)(Text(item,"type",Text(item,"tipo"))=="Servicio"?new JsonObject{["servicio_id"]=DbId(item),["cantidad"]=Number(item,"qty")}:new JsonObject{["producto_id"]=DbId(item),["caracteristicas_id"]=int.Parse(Text(item,"sku")),["cantidad"]=Number(item,"qty")})).ToArray());await Crud(c,tx,"cotizacion","insert",new(){["id"]=await Next(c,tx,"cotizacion","id",ct),["cliente_id"]=rut,["emprendedor_id"]=Text(row,"sellerRut"),["detalle"]=detail,["estado"]="Solicitada"},null,ct);}
    else await Crud(c,tx,"cotizacion","update",new(){["estado"]=Text(row,"status")},new(){["id"]=DbId(before)},ct);
   }
   else if(resource=="returns"){
    var orderId=int.Parse(Text(row,"orderId"));var productKey=Text(row,"productId").Split('-');var productId=int.Parse(productKey[1]);var variantId=int.Parse(Text(row,"sku"));var returnId=before==null?await Next(c,tx,"devolucion","id",ct):int.Parse(Id(before));
    if(before==null){var prior=await Query(c,tx,"SELECT jsonb_build_object('id',devolucion_id)::text FROM public.comprar WHERE venta_id=@order AND producto_id=@product AND caracteristicas_id=@variant AND devolucion_id IS NOT NULL",ct,("order",orderId),("product",productId),("variant",variantId));if(prior.Count>0)throw new ArgumentException("La compra ya tiene una devolución asociada.");var refund=await Query(c,tx,"SELECT jsonb_build_object('amount',round(b.preciounitario::numeric*@qty*(1-coalesce(v.descuento::numeric/nullif(v.valorbruto,0),0))*1.19))::text FROM public.comprar b JOIN public.venta v ON v.id=b.venta_id WHERE b.venta_id=@order AND b.producto_id=@product AND b.caracteristicas_id=@variant",ct,("qty",Number(row,"qty")),("order",orderId),("product",productId),("variant",variantId));await Crud(c,tx,"devolucion","insert",new(){["id"]=returnId,["valor"]=Number(refund[0],"amount"),["medio"]="Medio original",["motivo"]=Text(row,"reason")},null,ct);await Exec(c,tx,"INSERT INTO shopping_ui.return_requests(return_id,quantity,images) VALUES(@id,@qty,@images::jsonb)",ct,("id",returnId),("qty",(int)Number(row,"qty")),("images",(row?["images"]??new JsonArray()).ToJsonString()));}
    var state=Text(row,"status");if(state=="Finalizada")throw new ArgumentException("El esquema importado registra aprobación; el reembolso bancario requiere una pasarela.");await Crud(c,tx,"comprar","update",new(){["devolucion_id"]=returnId,["estadodevolucion"]=state,["fechadevolucion"]=DateTime.Today.ToString("yyyy-MM-dd"),["cantidaddevuelta"]=state=="Aprobada"?Number(row,"qty"):0},new(){["producto_id"]=productId,["caracteristicas_id"]=variantId,["venta_id"]=orderId},ct);
   }
   else if(resource=="users")await WriteUser(c,tx,row!,before,ct);
   else if(resource=="companies"){
    var fields=new JsonObject{["giro"]=Text(row,"category"),["nombre"]=Text(row,"name"),["web"]=Text(row,"website")};if(before==null)fields["rut"]=AccountService.Rut(Text(row,"rut"));await Crud(c,tx,"empresa",before==null?"insert":"update",fields,new(){["rut"]=Text(before,"rut",AccountService.Rut(Text(row,"rut")))},ct);
    var owner=AccountService.Rut(Text(row?["owner"],"run"));var ownerExists=await Query(c,tx,"SELECT jsonb_build_object('rut',run)::text FROM public.emprendedor WHERE run=@rut",ct,("rut",owner));if(ownerExists.Count==0)throw new ArgumentException("Registra primero el perfil emprendedor del propietario.");await Crud(c,tx,"emprendedor","update",new(){["empresa_id"]=AccountService.Rut(Text(row,"rut"))},new(){["run"]=owner},ct);await Contacts(c,tx,"empresa_id",AccountService.Rut(Text(row,"rut")),Text(row,"email"),Rows(row?["phones"]),ct);
    var ownerNames=Text(row?["owner"],"name").Trim().Split(' ',2);await Exec(c,tx,"UPDATE public.emprendedor SET nombre=@name,apellido=@surname WHERE run=@rut;UPDATE public.cliente SET nombre=@name,apellido=@surname WHERE run=@rut",ct,("name",ownerNames[0]),("surname",ownerNames.Length>1?ownerNames[1]:""),("rut",owner));var ownerClient=await Query(c,tx,"SELECT jsonb_build_object('id',run)::text FROM public.cliente WHERE run=@rut",ct,("rut",owner));await Contacts(c,tx,ownerClient.Count>0?"cliente_id":"emprendedor_id",owner,Text(row?["owner"],"email"),new JsonArray(Text(row?["owner"],"phone")),ct);
    var companyRut=AccountService.Rut(Text(row,"rut"));if(row?["hasPhysicalStore"]?.GetValue<bool>()==true){var commune=await Query(c,tx,"SELECT to_jsonb(t)::text FROM public.comuna t WHERE nombre=@name LIMIT 1",ct,("name",Text(row,"comuna")));var parsed=System.Text.RegularExpressions.Regex.Match(Text(row,"address").Trim(),@"^(.*\S)\s+(\d+)(?:\s+.*)?$");if(commune.Count==0||!parsed.Success)throw new ArgumentException("Indica una comuna existente y la dirección del local terminada en su número.");var linked=await Query(c,tx,"SELECT to_jsonb(t)::text FROM public.tienedirempresa t WHERE empresa_id=@rut LIMIT 1",ct,("rut",companyRut));var addressId=linked.Count>0?(int)Number(linked[0],"direccion_id"):await Next(c,tx,"direccion","id",ct);await Crud(c,tx,"direccion",linked.Count==0?"insert":"update",new(){["id"]=addressId,["calle"]=parsed.Groups[1].Value,["numero"]=int.Parse(parsed.Groups[2].Value),["comuna_id"]=Number(commune[0],"id")},new(){["id"]=addressId},ct);if(linked.Count==0)await Crud(c,tx,"tienedirempresa","insert",new(){["empresa_id"]=companyRut,["direccion_id"]=addressId},null,ct);}else await Exec(c,tx,"DELETE FROM public.tienedirempresa WHERE empresa_id=@rut",ct,("rut",companyRut));

   }
   else if(resource.StartsWith("addresses:")){
    if(before==null||!JsonNode.DeepEquals(before,row)){var id=before==null?await Next(c,tx,"direccion","id",ct):int.Parse(Id(before));var commune=await Query(c,tx,"SELECT to_jsonb(t)::text FROM public.comuna t WHERE nombre=@name ORDER BY id LIMIT 1",ct,("name",Text(row,"commune")));if(commune.Count==0||!int.TryParse(Text(row,"number"),out var number)||number<=0)throw new ArgumentException("Comuna o número de dirección inválidos.");await Crud(c,tx,"direccion",before==null?"insert":"update",new(){["id"]=id,["calle"]=Text(row,"street"),["numero"]=number,["pasaje"]=Text(row,"department"),["sector"]=Text(row,"reference"),["comuna_id"]=Number(commune[0],"id"),["cliente_id"]=rut},new(){["id"]=id},ct);if(before==null)await Crud(c,tx,"registrar","insert",new(){["cliente_id"]=rut,["direccion_id"]=id},null,ct);if(row?["primary"]?.GetValue<bool>()==true)await Exec(c,tx,"INSERT INTO shopping_ui.address_preferences VALUES(@rut,@id) ON CONFLICT(rut) DO UPDATE SET address_id=EXCLUDED.address_id",ct,("rut",rut),("id",id));}
   }
   else if(resource=="messages")await WriteMessage(c,tx,row!,rut,ct);
   else if(resource.StartsWith("questions:")||resource.StartsWith("reviews:"))await WriteInteraction(c,tx,resource,row!,before,rut,ct);
  }
  var kept=rows.Select(Id).ToHashSet();foreach(var removed in old.Where(row=>!kept.Contains(Id(row)))){
   if(resource=="catalog")await Exec(c,tx,"INSERT INTO shopping_ui.listing_state(id,active) VALUES(@id,false) ON CONFLICT(id) DO UPDATE SET active=false",ct,("id",Id(removed)));
   else if(resource=="companies")await Crud(c,tx,"empresa","delete",new(),new(){["rut"]=Text(removed,"rut")},ct);
   else if(resource=="users"){await Exec(c,tx,"INSERT INTO shopping_ui.principals(rut,active) VALUES(@rut,false) ON CONFLICT(rut) DO UPDATE SET active=false",ct,("rut",Text(removed,"rut")));}
   else if(resource.StartsWith("addresses:"))throw new ArgumentException("Las direcciones conservan referencias de compras; puedes editar o agregar otra.");
  }
 }
 public static async Task Contacts(NpgsqlConnection c,NpgsqlTransaction tx,string column,string rut,string email,JsonArray phones,CancellationToken ct){
  if(!new[]{"cliente_id","emprendedor_id","empresa_id"}.Contains(column))throw new ArgumentException("Contacto inválido.");
  foreach(var (table,field,values) in new[]{("correo","correo",email==""?new JsonArray():new JsonArray(email.Trim().ToLowerInvariant())),("telefono","telefono",phones)}){
   if(values.Count==0)continue;await Exec(c,tx,$"DELETE FROM public.{table} WHERE {column}=@rut",ct,("rut",rut));
   foreach(var item in values){var value=field=="telefono"?System.Text.RegularExpressions.Regex.Replace(item?.ToString()??"",@"[^+0-9]",""):item!.ToString();var affected=await Exec(c,tx,$"INSERT INTO public.{table}({field},{column}) VALUES(@value,@rut) ON CONFLICT({field}) DO UPDATE SET cliente_id=@client,emprendedor_id=@seller,empresa_id=@company WHERE coalesce({table}.cliente_id,{table}.emprendedor_id,{table}.empresa_id)=@rut",ct,("value",value),("rut",rut),("client",column=="cliente_id"?(object)rut:DBNull.Value),("seller",column=="emprendedor_id"?(object)rut:DBNull.Value),("company",column=="empresa_id"?(object)rut:DBNull.Value));if(affected==0)throw new ArgumentException("El contacto pertenece a otra cuenta.");}
  }
 }
 public static async Task WriteUser(NpgsqlConnection c,NpgsqlTransaction tx,JsonNode row,JsonNode? before,CancellationToken ct){
  var rut=AccountService.Rut(Text(row,"rut"));if(before!=null&&AccountService.Rut(Text(before,"rut"))!=rut)throw new ArgumentException("El RUT de una cuenta existente no se modifica.");
  var names=Text(row,"name").Trim().Split(' ',2);var roles=Rows(row["roles"]);if(names[0].Length<2||roles.Count==0||roles.Any(role=>role?.ToString() is not ("Cliente" or "Emprendedor")))throw new ArgumentException("Nombre o roles inválidos.");
  foreach(var role in roles){var table=role?.ToString()=="Emprendedor"?"emprendedor":"cliente";var present=await Query(c,tx,$"SELECT jsonb_build_object('present',true)::text FROM public.{table} WHERE run=@rut",ct,("rut",rut));var fields=new JsonObject{["nombre"]=names[0],["apellido"]=names.Length>1?names[1]:"",["fechanac"]=Text(row,"birthDate")};if(present.Count==0){fields["run"]=rut;fields["passwd"]="!CONFIGURAR-CONTRASEÑA!";}await Crud(c,tx,table,present.Count==0?"insert":"update",fields,new(){["run"]=rut},ct);}
  await Exec(c,tx,"UPDATE public.cliente SET nombre=@name,apellido=@surname,fechanac=@born::date WHERE run=@rut;UPDATE public.emprendedor SET nombre=@name,apellido=@surname,fechanac=@born::date WHERE run=@rut",ct,("rut",rut),("name",names[0]),("surname",names.Length>1?names[1]:""),("born",Text(row,"birthDate")));
  await Contacts(c,tx,roles.Any(role=>role?.ToString()=="Cliente")?"cliente_id":"emprendedor_id",rut,Text(row,"email"),Rows(row["phones"]),ct);
  if(Text(row,"address").Trim()!=""&&(before==null||Text(before,"address")!=Text(row,"address")||Number(before,"communeId")!=Number(row,"communeId"))){var parsed=System.Text.RegularExpressions.Regex.Match(Text(row,"address").Trim(),@"^(.*\S)\s+(\d+)(?:\s+.*)?$");var commune=(int)Number(row,"communeId");if(!parsed.Success||commune<=0)throw new ArgumentException("Completa dirección con calle, número y comuna.");var current=await Query(c,tx,"SELECT to_jsonb(t)::text FROM public.direccion t WHERE cliente_id=@rut OR emprendedor_id=@rut ORDER BY id LIMIT 1",ct,("rut",rut));var addressId=current.Count>0?(int)Number(current[0],"id"):await Next(c,tx,"direccion","id",ct);var fields=new JsonObject{["id"]=addressId,["calle"]=parsed.Groups[1].Value,["numero"]=int.Parse(parsed.Groups[2].Value),["comuna_id"]=commune};var buyer=roles.Any(role=>role?.ToString()=="Cliente");fields[buyer?"cliente_id":"emprendedor_id"]=rut;await Crud(c,tx,"direccion",current.Count>0?"update":"insert",fields,new(){["id"]=addressId},ct);if(buyer)await Exec(c,tx,"INSERT INTO public.registrar(cliente_id,direccion_id) VALUES(@rut,@id) ON CONFLICT DO NOTHING",ct,("rut",rut),("id",addressId));}
  await Exec(c,tx,"INSERT INTO shopping_ui.principals(rut,active,allowed_roles) VALUES(@rut,@active,@roles::jsonb) ON CONFLICT(rut) DO UPDATE SET active=EXCLUDED.active,allowed_roles=EXCLUDED.allowed_roles",ct,("rut",rut),("active",Text(row,"status")!="Inactivo"),("roles",roles.ToJsonString()));
 }
 static async Task WriteMessage(NpgsqlConnection c,NpgsqlTransaction tx,JsonNode row,string rut,CancellationToken ct){var threads=await Query(c,tx,"SELECT payload::text FROM shopping_ui.documents WHERE id='global:conversations'",ct);var thread=Rows(threads.FirstOrDefault()).FirstOrDefault(t=>Id(t)==Text(row,"conversationId"));var id=Text(row,"conversationId");string type,item,buyer,seller;
  if(thread!=null){var parts=Text(thread,"productId").Split('-');type=parts[0]=="S"?"Servicio":"Producto";item=parts[1];buyer=Text(thread,"customerRut");seller=Text(thread,"sellerRut");}
  else{var parts=id.Split(':');if(parts.Length!=4)throw new ArgumentException("Conversación inválida.");type=parts[0]=="S"?"Servicio":"Producto";item=parts[1];buyer=parts[2];seller=parts[3];}
  var messageId=await Next(c,tx,"mensajeria","id",ct);await Crud(c,tx,"mensajeria","insert",new(){["id"]=messageId,["texto"]=Text(row,"text"),["emisor"]=rut==seller?"Emprendedor":"Cliente"},null,ct);await Crud(c,tx,type=="Servicio"?"comunicars":"comunicarp","insert",new(){[type=="Servicio"?"servicio_id":"producto_id"]=int.Parse(item),["mensajeria_id"]=messageId,["cliente_id"]=buyer,["emprendedor_id"]=seller},null,ct);
 }
 static async Task WriteInteraction(NpgsqlConnection c,NpgsqlTransaction tx,string key,JsonNode row,JsonNode? before,string rut,CancellationToken ct){var parts=key[(key.IndexOf(':')+1)..].Split('-');var service=parts[0]=="S";var item=int.Parse(parts[1]);var seller=string.Join('-',parts.Skip(2));
  if(key.StartsWith("questions:")){
   if(before==null){var id=await Next(c,tx,"pregunta","id",ct);await Crud(c,tx,"pregunta","insert",new(){["id"]=id,["texto"]=Text(row,"question")},null,ct);await Crud(c,tx,service?"preguntars":"preguntarp","insert",new(){["pregunta_id"]=id,[service?"servicio_id":"producto_id"]=item,["cliente_id"]=rut,["emprendedor_id"]=seller},null,ct);}
   else{var id=await Next(c,tx,"mensajeria","id",ct);await Crud(c,tx,"mensajeria","insert",new(){["id"]=id,["texto"]=Text(row,"answer"),["emisor"]="Emprendedor"},null,ct);await Crud(c,tx,service?"comunicars":"comunicarp","insert",new(){["mensajeria_id"]=id,[service?"servicio_id":"producto_id"]=item,["cliente_id"]=Text(before,"customerRut"),["emprendedor_id"]=seller,["pregunta_id"]=int.Parse(Id(before))},null,ct);}
  }else{
   var line=await Query(c,tx,$"SELECT to_jsonb(x)::text FROM public.{(service?"contratar":"comprar")} x JOIN public.venta v ON v.id=x.venta_id WHERE x.cliente_id=@rut AND x.emprendedor_id=@seller AND x.{(service?"servicio_id":"producto_id")}=@item AND v.estado IN ('Entregado','Recibido') ORDER BY x.venta_id DESC LIMIT 1",ct,("rut",rut),("seller",seller),("item",item));if(line.Count==0)throw new ArgumentException("Necesitas una compra entregada para calificar.");var id=await Next(c,tx,"calificacion","id",ct);await Crud(c,tx,"calificacion","insert",new(){["id"]=id,["puntaje"]=Number(row,"rating"),["comentario"]=Text(row,"comment")},null,ct);var fields=new JsonObject{[service?"servicio_id":"producto_id"]=item,["calificacion_id"]=id,["venta_id"]=Number(line[0],"venta_id"),["cliente_id"]=rut,["emprendedor_id"]=seller};if(!service)fields["caracteristicas_id"]=Number(line[0],"caracteristicas_id");await Crud(c,tx,service?"calificars":"calificarp","insert",fields,null,ct);
  }
 }
}
